function checkTickets(olgaAttempt) {
    const bridgeCitySchedule = {
        "Mon": { start: 9, end: 15 },
        "Thu": { start: 9, end: 15 },
        "Fri": { start: 9, end: 12 }
    };

    let success = false;

    for (const day in bridgeCitySchedule) {
        const schedule = bridgeCitySchedule[day];
        if (olgaAttempt.day === day && olgaAttempt.time >= schedule.start && olgaAttempt.time < schedule.end) {
            success = true;
            break;
        }
    }

    return success ? "Success" : "Failure";
}

// Test cases
