    const mondaySchedule = "Mon–Thu 09:00–15:00, Friday 09:00–12:00";

    // Check if the Friday attempt is valid
    const fridayStart = new Date("2023-04-01T11:50");
    const fridayEnd = new Date(fridayStart.getTime() + (15 * 60 * 1000));
