    const fridayBreakEnd = new Date(fridayStart.getTime() + (11 * 60 * 1000) + 20 * 1000);
    if (fridayAttempt >= fridayStart && fridayAttempt < fridayEnd && !fridayAttempt.between(fridayBreakStart, fridayBreakEnd)) {
        return "Friday attempt succeeds";
