    const mondayEnd = new Date(mondayStart.getTime() + (15 * 60 * 1000));
    const mondayBreakStart = new Date(mondayStart.getTime() + (11 * 60 * 1000));
    const mondayBreakEnd = new Date(mondayStart.getTime() + (11 * 60 * 1000) + 20 * 1000);
    if (mondayAttempt >= mondayStart && mondayAttempt < mondayEnd && !mondayAttempt.between(mondayBreakStart, mondayBreakEnd)) {
        return "Monday attempt succeeds";
    }

    return "Neither attempt succeeds";
}
