function computeEarliestSafeCompletionTime() {
    const A = 7;
    const B = 11;
    const C = 17;
    const D = 6;
    const E = 12;
    const safetyBuffer = 4;

    // Calculate the earliest start time for B and C
    let earliestBStart = Math.max(A + safetyBuffer, B);
    let earliestCStart = Math.max(A + safetyBuffer, C);

    // Calculate the completion time of D
    let DCompletionTime = earliestBStart + D;
    if (DCompletionTime > E) {
        return "Plan does not meet the limit.";
    }

    // Calculate the completion time of E
    let ECompletionTime = Math.max(DCompletionTime, E);

    // The earliest safe completion time is when E finishes
    const earliestSafeCompletionTime = ECompletionTime + safetyBuffer;

    return `The earliest safe completion time is ${earliestSafeCompletionTime} minutes.`;
}
